import {repository,dayKey,uid,stores,DATABASE_VERSION} from './store.js';
import {sessionTransition} from './engine.js';
import {validateBackup} from './backup.js';
export function createActions(repo=repository,clock=()=>new Date()){
 const date=()=>dayKey(clock()),at=()=>clock().toISOString();
 const finite=(v,min,max,label)=>{if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max)throw Error(label+' is outside the allowed range.')};
 const editable=s=>{if(!s||!['active','paused'].includes(s.status))throw Error('This historical session is protected. Use a deliberate correction.')};
 const ensureDay=async t=>{const d=date();if(!await t.get('dailyStates',d))await t.put('dailyStates',{id:d,date:d,createdAt:at()});return d};
 const registry={
  async saveRecord({store,record}){if(!['preferences','templates','events','attempts','metrics','checkins','exercises','goals'].includes(store))throw Error('This record type needs a dedicated action.');return repo.transact(stores,async t=>{const tables=Object.fromEntries(await Promise.all(stores.map(async s=>[s,await t.all(s)])));const index=tables[store].findIndex(r=>r.id===record.id);if(index<0)tables[store].push(record);else tables[store][index]=record;validateBackup({format:'kitty-quest-backup',schemaVersion:DATABASE_VERSION,tables});await t.put(store,record);return record})},
  async ensureDay(){return repo.transact(['dailyStates','templates'],async t=>{const d=await ensureDay(t),state=await t.get('dailyStates',d);if(!state.routineTasks){const current=await t.get('templates','routine'),next=await t.get('templates','routine-next');state.routineTasks=next&&next.effective<=d?next.tasks:current?.tasks||['Brush teeth','Get ready','Prepare your day','Review tomorrow','Evening wind-down'];await t.put('dailyStates',state)}return d})},
  async saveConfiguration({configuration:c}){for(const [k,min,max] of [['startWeight',50,1000],['goalLow',50,1000],['goalHigh',c.goalLow,1000],['laterMilestone',50,1000],['durationWeeks',1,104],['weeklyLossLow',0,5],['weeklyLossHigh',c.weeklyLossLow,5]])finite(c[k],min,max,k);if(!Number.isInteger(c.durationWeeks)||c.id!=='transformation')throw Error('Invalid transformation configuration.');return repo.put('configurations',c)},
  async addWater({amount}){finite(amount,0.1,256,'Water amount');return repo.transact(['water','dailyStates'],async t=>{const d=await ensureDay(t);const log={id:uid(),date:d,amount,at:at()};await t.put('water',log);return log})},
  async startSession({kind,exercises,name}){if(!['Main','Second','Extra','Sports','Custom'].includes(kind))throw Error('Unknown session kind.');if(!Array.isArray(exercises)||!exercises.length)throw Error('A session needs exercises.');return repo.transact(['sessions','dailyStates'],async t=>{const d=await ensureDay(t);if(['Main','Second'].includes(kind)){const existing=(await t.all('sessions')).find(s=>s.date===d&&s.kind===kind&&!s.supersededBy);if(existing)return existing}const s=sessionTransition({id:uid(),date:d,kind,name,status:'planned',exercises:structuredClone(exercises),logs:[],startedAt:at(),revision:0,...(['Main','Second'].includes(kind)?{slotKey:d+':'+kind}:{})},'start');await t.put('sessions',s);return s})},
  async logSet({sessionId,exercise,...values}){finite(values.reps,0,1000,'Reps');finite(values.weight,0,2000,'Resistance');finite(values.difficulty,1,10,'Difficulty');return repo.transact(['sessions'],async t=>{const s=await t.get('sessions',sessionId);editable(s);if(s.status!=='active')throw Error('Resume the session first.');if(!s.exercises[exercise])throw Error('Unknown exercise.');const log={...values,id:uid(),exercise,name:s.exercises[exercise].name,at:at()};s.logs.push(log);await t.put('sessions',s);return log})},
  async transitionSession({sessionId,action}){if(!['pause','resume','end'].includes(action))throw Error('Use a dedicated start or completion action.');return repo.transact(['sessions'],async t=>{const s=await t.get('sessions',sessionId);if(!s)throw Error('Session not found.');const next=sessionTransition(s,action);await t.put('sessions',next);return next})},
  async completeSession({sessionId,difficulty,notes=''}){finite(difficulty,1,10,'Difficulty');return repo.transact(['sessions','rewards'],async t=>{const s=await t.get('sessions',sessionId);if(!s)throw Error('Session not found.');if(s.status==='completed')return s;const next={...sessionTransition(s,'complete'),difficulty,notes,completedAt:at()};await t.put('sessions',next);if(next.logs.some(l=>l.reps>0&&!l.pain)){const id='session:'+s.id;if(!await t.get('rewards',id))await t.put('rewards',{id,source:s.id,date:s.date,xp:50,coins:10,at:at()})}return next})},
  async replaceExercise({sessionId,index,exercise}){return repo.transact(['sessions'],async t=>{const s=await t.get('sessions',sessionId);editable(s);if(!s.exercises[index])throw Error('Unknown exercise.');s.exercises[index]={...s.exercises[index],...exercise};await t.put('sessions',s);return s})},
  async correctSet({sessionId,setId,changes,reason}){if(typeof reason!=='string'||!reason.trim())throw Error('A correction needs a reason.');if(Object.keys(changes).some(k=>!['reps','weight','difficulty','notes'].includes(k)))throw Error('Unsupported correction field.');for(const [k,min,max] of [['reps',0,1000],['weight',0,2000],['difficulty',1,10]])if(k in changes)finite(changes[k],min,max,k);return repo.transact(['sessions','edits'],async t=>{const s=await t.get('sessions',sessionId);if(!s||!['completed','partial'].includes(s.status))throw Error('Corrections apply to ended sessions.');const index=s.logs.findIndex(l=>l.id===setId);if(index<0)throw Error('Set not found.');const before=structuredClone(s.logs[index]),after={...before,...changes};s.logs[index]=after;s.revision=(s.revision||0)+1;await t.put('edits',{id:uid(),recordId:s.id,setId,revision:s.revision,reason:reason.trim(),before,after,at:at()});await t.put('sessions',s);return s})},
  async moveScheduleEvent({eventId,time,date:targetDate,status='MOVED'}){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)||!/^\d{4}-\d{2}-\d{2}$/.test(targetDate))throw Error('Enter a valid date and time.');if(!['PLANNED','COMPLETED','SKIPPED','MOVED','MISSED'].includes(status))throw Error('Unknown event status.');return repo.transact(['events'],async t=>{const e=await t.get('events',eventId);if(!e)throw Error('Schedule event not found.');const next={...e,time,date:targetDate,status};await t.put('events',next);return next})},
  async moveWorkoutToTonight({sessionId,time='20:00'}){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))throw Error('Enter a valid time.');return repo.transact(['sessions','events','dailyStates'],async t=>{const s=await t.get('sessions',sessionId);if(!s)throw Error('Session not found.');if(['completed','partial'].includes(s.status))throw Error('An ended workout cannot be rescheduled.');const d=await ensureDay(t),id='workout:'+s.id;const e=await t.get('events',id);const next={...e,id,date:d,time,name:s.name,sessionId:s.id,status:'MOVED',buffer:e?.buffer||0};await t.put('events',next);return next})},
  async setRoutineTask({task,done}){return repo.transact(['routineLogs','dailyStates'],async t=>{const d=await ensureDay(t);await t.put('routineLogs',{id:d+':'+task,date:d,task,done})})}
 };
 // All interaction surfaces dispatch the same domain actions.
 return {...registry,async dispatch(name,input){if(!Object.hasOwn(registry,name))throw Error('Unsupported command.');return registry[name](input)}};
}
export const actions=createActions();
